// frontend/src/components/Sidebar.jsx
import React, { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import ProfileMenu from "./ProfileMenu";
import "./Sidebar.css";

export default function Sidebar({ sessions = [], onLoadSession = () => {}, onNewChat = () => {} }) {
  const [remoteSessions, setRemoteSessions] = useState([]);
  const [loadingDelete, setLoadingDelete] = useState(null); // id being deleted
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    fetch("/api/sessions/list")
      .then((r) => (r.ok ? r.json() : []))
      .then((data) => {
        if (Array.isArray(data)) setRemoteSessions(data);
      })
      .catch(() => setRemoteSessions([]));
  }, []);

  const mergedSessions = React.useMemo(() => {
    const map = new Map();
    (sessions || []).forEach((s) => {
      if (s && s.id) map.set(String(s.id), s);
    });
    (remoteSessions || []).forEach((rs) => {
      if (rs && rs.id && !map.has(String(rs.id))) map.set(String(rs.id), rs);
    });
    return Array.from(map.values()).slice(0, 50);
  }, [sessions, remoteSessions]);

  const navBtnStyle = {
    display: "block",
    width: "100%",
    padding: "8px 10px",
    borderRadius: 8,
    background: "#fff",
    border: "1px solid #e6eef8",
    textAlign: "left",
    cursor: "pointer",
  };

  function handleNewChat() {
    try {
      onNewChat();
    } catch (e) {
      console.error("onNewChat callback error:", e);
    }
    navigate("/");
  }

  function handleLoadSession(sess) {
    try {
      onLoadSession(sess);
    } catch (e) {
      console.error("onLoadSession callback error:", e);
    }
    navigate("/");
  }

  async function handleDeleteSession(id) {
    if (!id) return;
    if (!window.confirm("Delete this chat? This action cannot be undone.")) return;
    setLoadingDelete(id);
    try {
      const resp = await fetch(`/api/sessions/${encodeURIComponent(id)}`, { method: "DELETE" });
      if (!resp.ok) {
        const text = await resp.text();
        throw new Error(text || "Failed to delete session");
      }
      // remove from remoteSessions and local sessions lists
      setRemoteSessions((rs) => rs.filter((r) => String(r.id) !== String(id)));
      // also remove from localStorage if present
      try {
        const raw = localStorage.getItem("ai_chat_sessions");
        if (raw) {
          const arr = JSON.parse(raw).filter((x) => String(x.id) !== String(id));
          localStorage.setItem("ai_chat_sessions", JSON.stringify(arr));
        }
      } catch (e) {}
    } catch (e) {
      console.error("Delete failed:", e);
      alert("Failed to delete session.");
    } finally {
      setLoadingDelete(null);
    }
  }

  return (
    <aside className="sidebar-root">
      <div className="sidebar-top">
        <button className="btn-new" onClick={handleNewChat}>+ New Chat</button>

        <div className="sidebar-title">Chat History</div>

        <div className="session-list">
          {mergedSessions.length === 0 && <div className="empty">No saved chats yet</div>}

          {mergedSessions.slice(0, 20).map((s) => (
            <div key={s.id} className="session-row">
              <div
                className="session-body"
                onClick={() => handleLoadSession(s)}
                title={s.title || `Open chat ${s.id}`}
              >
                <div className="session-title">{s.title || `Trip ${new Date(s.createdAt || Date.now()).toLocaleString()}`}</div>
                <div className="session-meta">{s.prompt ? s.prompt.slice(0, 60) : ""}</div>
              </div>

              <div className="session-actions">
                <button
                  className="btn-delete"
                  onClick={(e) => { e.stopPropagation(); handleDeleteSession(s.id); }}
                  disabled={loadingDelete === s.id}
                  title="Delete chat"
                >
                  {loadingDelete === s.id ? "..." : "🗑"}
                </button>
              </div>
            </div>
          ))}
        </div>

        <div className="sidebar-title" style={{ marginTop: 12 }}>Navigation</div>

        <div className="nav-list">
          <Link to="/flights" className="nav-link"><button style={{ ...navBtnStyle, borderColor: location.pathname === "/flights" ? "#C4B5FD" : navBtnStyle.border }}>✈️ Flight Search</button></Link>
          <Link to="/hotels" className="nav-link"><button style={{ ...navBtnStyle, borderColor: location.pathname === "/hotels" ? "#C4B5FD" : navBtnStyle.border }}>🏨 Hotels & Cuisines</button></Link>
          <Link to="/news" className="nav-link"><button style={{ ...navBtnStyle, borderColor: location.pathname === "/news" ? "#C4B5FD" : navBtnStyle.border }}>📰 Travel News & Blogs</button></Link>
        </div>
      </div>

      <div className="sidebar-bottom">
        <ProfileMenu />
      </div>
    </aside>
  );
}
